import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";

import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Container,
  Grid,
  Card,
  CardContent,
  Button,
  Chip,
  IconButton,
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Divider,
  Alert,
  CircularProgress,
} from "@mui/material";

import {
  Menu as MenuIcon,
  Restaurant,
  ReceiptLong,
  LocalFireDepartment,
  CheckCircle,
  DoneAll,
  Logout,
  Dashboard,
  Inventory,
} from "@mui/icons-material";

const StaffDashboard = ({ user, onLogout }) => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [activePage, setActivePage] = useState("dashboard");

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(false);

  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError("");

      const response = await axios.get("/api/tokens");

      setOrders(
        Array.isArray(response.data)
          ? response.data
          : []
      );
    } catch (err) {
      console.error("Error fetching orders:", err);

      setError(
        err.response?.data?.message ||
        "Unable to load orders."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();

    const interval = setInterval(() => {
      fetchOrders();
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  const updateStatus = async (id, status) => {
    try {
      setError("");
      setMessage("");

      await axios.patch(
        `/api/tokens/${id}/status`,
        { status }
      );

      setMessage(
        `Order status changed to ${status}.`
      );

      await fetchOrders();
    } catch (err) {
      console.error("Status update error:", err);

      setError(
        err.response?.data?.message ||
        "Unable to update order status."
      );
    }
  };

  const pendingOrders = useMemo(
    () =>
      orders.filter(
        (order) => order.status === "Pending"
      ),
    [orders]
  );

  const preparingOrders = useMemo(
    () =>
      orders.filter(
        (order) => order.status === "Preparing"
      ),
    [orders]
  );

  const readyOrders = useMemo(
    () =>
      orders.filter(
        (order) => order.status === "Ready"
      ),
    [orders]
  );

  const servedOrders = useMemo(
    () =>
      orders.filter(
        (order) => order.status === "Served"
      ),
    [orders]
  );

  const navigate = (page) => {
    setActivePage(page);
    setDrawerOpen(false);
    setMessage("");
    setError("");
  };

  const renderOrderCard = (order) => (
    <Card
      key={order._id}
      sx={{
        borderRadius: 3,
        mb: 2,
        boxShadow:
          "0 4px 15px rgba(0,0,0,0.08)",
      }}
    >
      <CardContent>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-start",
            gap: 2,
            mb: 2,
          }}
        >
          <Box>
            <Typography
              variant="h6"
              sx={{
                fontWeight: 800,
              }}
            >
              {order.itemName}
            </Typography>

            <Typography color="text.secondary">
              Customer: {order.customerName}
            </Typography>

            <Typography color="text.secondary">
              Quantity: {order.quantity}
            </Typography>

            <Typography color="text.secondary">
              Total: ₹
              {order.price * order.quantity}
            </Typography>
          </Box>

          <Chip
            label={order.status}
            color={
              order.status === "Pending"
                ? "info"
                : order.status === "Preparing"
                  ? "warning"
                  : order.status === "Ready"
                    ? "success"
                    : "default"
            }
          />
        </Box>

        {order.specialInstructions && (
          <Alert
            severity="info"
            sx={{ mb: 2 }}
          >
            {order.specialInstructions}
          </Alert>
        )}

        <Box
          sx={{
            display: "flex",
            gap: 1,
            flexWrap: "wrap",
          }}
        >
          {order.status === "Pending" && (
            <Button
              variant="contained"
              color="warning"
              startIcon={
                <LocalFireDepartment />
              }
              onClick={() =>
                updateStatus(
                  order._id,
                  "Preparing"
                )
              }
            >
              Start Preparing
            </Button>
          )}

          {order.status === "Preparing" && (
            <Button
              variant="contained"
              color="success"
              startIcon={<CheckCircle />}
              onClick={() =>
                updateStatus(
                  order._id,
                  "Ready"
                )
              }
            >
              Mark Ready
            </Button>
          )}

          {order.status === "Ready" && (
            <Button
              variant="contained"
              color="success"
              startIcon={<DoneAll />}
              onClick={() =>
                updateStatus(
                  order._id,
                  "Served"
                )
              }
            >
              Mark Served
            </Button>
          )}
        </Box>
      </CardContent>
    </Card>
  );

  const renderDashboard = () => (
    <>
      <Box
        sx={{
          mb: 4,
          p: 4,
          borderRadius: 4,
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
          color: "white",
        }}
      >
        <Typography
          variant="h4"
          sx={{ fontWeight: 800 }}
        >
          Welcome, {user.name}
        </Typography>

        <Typography sx={{ mt: 1 }}>
          Staff Kitchen Dashboard
        </Typography>
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent sx={{ textAlign: "center" }}>
              <ReceiptLong
                sx={{
                  fontSize: 45,
                  color: "#1976d2",
                }}
              />

              <Typography
                variant="h4"
                sx={{ fontWeight: 800 }}
              >
                {orders.length}
              </Typography>

              <Typography>
                Total Orders
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent sx={{ textAlign: "center" }}>
              <ReceiptLong
                sx={{
                  fontSize: 45,
                  color: "#0288d1",
                }}
              />

              <Typography
                variant="h4"
                sx={{ fontWeight: 800 }}
              >
                {pendingOrders.length}
              </Typography>

              <Typography>
                Pending
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent sx={{ textAlign: "center" }}>
              <LocalFireDepartment
                sx={{
                  fontSize: 45,
                  color: "#ed6c02",
                }}
              />

              <Typography
                variant="h4"
                sx={{ fontWeight: 800 }}
              >
                {preparingOrders.length}
              </Typography>

              <Typography>
                Preparing
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent sx={{ textAlign: "center" }}>
              <CheckCircle
                sx={{
                  fontSize: 45,
                  color: "#2e7d32",
                }}
              />

              <Typography
                variant="h4"
                sx={{ fontWeight: 800 }}
              >
                {readyOrders.length}
              </Typography>

              <Typography>
                Ready
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Box sx={{ mt: 5 }}>
        <Typography
          variant="h5"
          sx={{
            fontWeight: 800,
            color: "#2E7D32",
            mb: 3,
          }}
        >
          Active Orders
        </Typography>

        {loading ? (
          <Box sx={{ textAlign: "center", py: 5 }}>
            <CircularProgress />
          </Box>
        ) : pendingOrders.length === 0 &&
          preparingOrders.length === 0 &&
          readyOrders.length === 0 ? (
          <Card sx={{ p: 5, textAlign: "center" }}>
            <Typography variant="h6">
              No active orders
            </Typography>
          </Card>
        ) : (
          <>
            {pendingOrders.map(renderOrderCard)}
            {preparingOrders.map(renderOrderCard)}
            {readyOrders.map(renderOrderCard)}
          </>
        )}
      </Box>
    </>
  );

  const renderNewOrders = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        New Orders
      </Typography>

      {pendingOrders.length === 0 ? (
        <Card sx={{ p: 5, textAlign: "center" }}>
          <Typography variant="h6">
            No new orders
          </Typography>
        </Card>
      ) : (
        pendingOrders.map(renderOrderCard)
      )}
    </>
  );

  const renderPreparing = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Preparing Orders
      </Typography>

      {preparingOrders.length === 0 ? (
        <Card sx={{ p: 5, textAlign: "center" }}>
          <Typography variant="h6">
            No orders are currently being prepared
          </Typography>
        </Card>
      ) : (
        preparingOrders.map(renderOrderCard)
      )}
    </>
  );

  const renderReady = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Ready Orders
      </Typography>

      {readyOrders.length === 0 ? (
        <Card sx={{ p: 5, textAlign: "center" }}>
          <Typography variant="h6">
            No ready orders
          </Typography>
        </Card>
      ) : (
        readyOrders.map(renderOrderCard)
      )}
    </>
  );

  const renderServed = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Served Orders
      </Typography>

      {servedOrders.length === 0 ? (
        <Card sx={{ p: 5, textAlign: "center" }}>
          <Typography variant="h6">
            No served orders yet
          </Typography>
        </Card>
      ) : (
        servedOrders.map(renderOrderCard)
      )}
    </>
  );

  const renderMenuAvailability = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Menu Availability
      </Typography>

      <Card sx={{ p: 4 }}>
        <Typography variant="h6">
          Menu availability module
        </Typography>

        <Typography
          color="text.secondary"
          sx={{ mt: 1 }}
        >
          This module will be connected to the MongoDB
          menu collection in the next development step.
        </Typography>
      </Card>
    </>
  );

  const renderPage = () => {
    if (activePage === "dashboard")
      return renderDashboard();

    if (activePage === "newOrders")
      return renderNewOrders();

    if (activePage === "preparing")
      return renderPreparing();

    if (activePage === "ready")
      return renderReady();

    if (activePage === "served")
      return renderServed();

    if (activePage === "menu")
      return renderMenuAvailability();

    return renderDashboard();
  };

  return (
    <Box
      sx={{
        minHeight: "100vh",
        backgroundColor: "#f5f7f5",
      }}
    >
      <AppBar
        position="sticky"
        sx={{
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            onClick={() => setDrawerOpen(true)}
          >
            <MenuIcon />
          </IconButton>

          <Restaurant sx={{ mx: 1 }} />

          <Typography
            variant="h5"
            sx={{
              fontWeight: 800,
              flexGrow: 1,
            }}
          >
            CanteenPro
          </Typography>

          <Typography
            sx={{
              mr: 2,
              display: { xs: "none", sm: "block" },
            }}
          >
            Staff
          </Typography>
        </Toolbar>
      </AppBar>

      <Drawer
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
      >
        <Box sx={{ width: 280 }}>
          <Box
            sx={{
              p: 3,
              background:
                "linear-gradient(135deg, #2E7D32, #4CAF50)",
              color: "white",
            }}
          >
            <Typography
              variant="h5"
              sx={{ fontWeight: 800 }}
            >
              CanteenPro
            </Typography>

            <Typography>
              Staff Panel
            </Typography>
          </Box>

          <List>
            <ListItemButton
              onClick={() => navigate("dashboard")}
            >
              <ListItemIcon>
                <Dashboard />
              </ListItemIcon>

              <ListItemText primary="Dashboard" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("newOrders")}
            >
              <ListItemIcon>
                <ReceiptLong />
              </ListItemIcon>

              <ListItemText primary="New Orders" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("preparing")}
            >
              <ListItemIcon>
                <LocalFireDepartment />
              </ListItemIcon>

              <ListItemText primary="Preparing" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("ready")}
            >
              <ListItemIcon>
                <CheckCircle />
              </ListItemIcon>

              <ListItemText primary="Ready" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("served")}
            >
              <ListItemIcon>
                <DoneAll />
              </ListItemIcon>

              <ListItemText primary="Served" />
            </ListItemButton>

            <ListItemButton
              onClick={() => navigate("menu")}
            >
              <ListItemIcon>
                <Inventory />
              </ListItemIcon>

              <ListItemText primary="Menu Availability" />
            </ListItemButton>

            <Divider />

            <ListItemButton onClick={onLogout}>
              <ListItemIcon>
                <Logout color="error" />
              </ListItemIcon>

              <ListItemText
                primary="Logout"
                sx={{ color: "error.main" }}
              />
            </ListItemButton>
          </List>
        </Box>
      </Drawer>

      <Container
        maxWidth="xl"
        sx={{ py: 4 }}
      >
        {message && (
          <Alert
            severity="success"
            sx={{ mb: 3 }}
          >
            {message}
          </Alert>
        )}

        {error && (
          <Alert
            severity="error"
            sx={{ mb: 3 }}
          >
            {error}
          </Alert>
        )}

        {renderPage()}
      </Container>
    </Box>
  );
};

export default StaffDashboard;
